#include <vector>
#include <omp.h>

bool reduceLogicalXOR(std::vector<bool> const& x) {
    int xor_acc = 0; // use int for OpenMP reduction portability

    #pragma omp parallel for reduction(^:xor_acc)
    for (std::size_t i = 0; i < x.size(); ++i) {
        xor_acc ^= static_cast<int>(x[i]);
    }

    return xor_acc != 0;
}
